(()=>{const e=document.querySelector(".book-container"),t=e?.querySelector(".book");if(!t||!window.matchMedia("(pointer: fine)").matches)return;const n=window.matchMedia("(prefers-reduced-motion: reduce)"),o=()=>{t.style.transform=""};e.addEventListener("pointermove",(o=>{if("mouse"!==o.pointerType||n.matches)return;const r=e.getBoundingClientRect(),i=(o.clientX-r.left)/r.width*2-1,d=(o.clientY-r.top)/r.height*2-1;t.style.transform=`rotateY(${4*i}deg) rotateX(${4*-d}deg)`})),e.addEventListener("pointerleave",o),n.addEventListener("change",o)})();